use sqlx::Row;
use serde::Serialize;
use serde_json::Value;
use subtle::ConstantTimeEq;

const MAX_FORMATTER_MARKER_BYTES: usize = 80;
pub(super) fn validated_irs_formatter(value:Option<&Value>)->Result<Option<Value>,&'static str>{let Some(value)=value else{return Ok(None)};let Value::Object(map)=value else{return Err("formatter must be an object")};if map.keys().any(|key|key!="sn"){return Err("only sn markers are allowed")}let Some(sn)=map.get("sn")else{return Ok(Some(serde_json::json!({"sn":{"start":"","end":""}})))};let Value::Object(sn)=sn else{return Err("sn must be an object")};if sn.keys().any(|key|key!="start"&&key!="end"){return Err("only sn.start and sn.end are allowed")}let marker=|k:&str|->Result<String,&'static str>{match sn.get(k){None=>Ok(String::new()),Some(Value::String(v))if v.len()<=MAX_FORMATTER_MARKER_BYTES=>Ok(v.clone()),Some(Value::String(_))=>Err("sn markers must be at most 80 bytes"),_=>Err("sn markers must be strings")}};Ok(Some(serde_json::json!({"sn":{"start":marker("start")?,"end":marker("end")?}})))}
pub(super) fn constant_time_required_match(payload:Option<&Value>,config:&Value,aliases:&[&str],key:&str)->bool{let expected=config.get(key).and_then(Value::as_str).unwrap_or("");if expected.is_empty(){return false}let Some(payload)=payload else{return false};let Some(provided)=text_value(payload,aliases)else{return false};expected.len()==provided.len()&&bool::from(expected.as_bytes().ct_eq(provided.as_bytes()))}
pub(super) fn irs_admin_order_item_sql(r:&sqlx::postgres::PgRow)->IrsAdminOrderItem{let s:Value=r.try_get("snapshot").unwrap_or_default();let v:Value=r.try_get("response").unwrap_or_default();let get=|k:&str|v.get(k).and_then(Value::as_str).or_else(||s.get(k).and_then(Value::as_str)).unwrap_or_default().to_owned();IrsAdminOrderItem{id:r.try_get("id").unwrap_or_default(),ref_id:r.try_get("reference_id").unwrap_or_default(),internal_ref_id:get("internalRefId"),irs_code:get("irsCode").if_empty_owned(r.try_get("buyer_sku_code").unwrap_or_default()),target:r.try_get("customer_no").unwrap_or_default(),status:r.try_get("status").unwrap_or_default(),status_code:get("statusCode"),message:v.get("message").and_then(Value::as_str).unwrap_or_default().to_owned(),sn:v.get("sn").and_then(Value::as_str).unwrap_or_default().to_owned(),vendor_trx_id:r.try_get("vendor_reference").unwrap_or_default(),request_ip:s.get("requestIp").and_then(Value::as_str).unwrap_or_default().to_owned(),created_at:r.try_get::<chrono::DateTime<chrono::Utc>,_>("created_at").map(|v|v.to_rfc3339()).unwrap_or_default(),updated_at:r.try_get::<chrono::DateTime<chrono::Utc>,_>("updated_at").map(|v|v.to_rfc3339()).unwrap_or_default()}}
pub(super) fn irs_log_item_sql(r:&sqlx::postgres::PgRow)->IrsLogItem{IrsLogItem{id:r.try_get("id").unwrap_or_default(),timestamp:r.try_get::<chrono::DateTime<chrono::Utc>,_>("created_at").map(|v|v.to_rfc3339()).unwrap_or_default(),event:r.try_get::<String,_>("event").unwrap_or_else(|_|"request".into()),ref_id:r.try_get("reference_id").unwrap_or_default(),status:r.try_get("status").unwrap_or_default(),message:r.try_get("message").unwrap_or_default(),verified:r.try_get("verified").unwrap_or(false),request_ip:r.try_get("request_ip").unwrap_or_default()}}
trait OwnedFallback{fn if_empty_owned(self,fallback:String)->String;}impl OwnedFallback for String{fn if_empty_owned(self,fallback:String)->String{if self.is_empty(){fallback}else{self}}}
