pub(super)fn text_value(p:&Value,keys:&[&str])->Option<String>{keys.iter().find_map(|k|p.get(*k).and_then(|v|match v{Value::String(s)=>Some(s.trim().to_owned()),Value::Number(n)=>Some(n.to_string()),Value::Bool(b)=>Some(b.to_string()),_=>None}).filter(|v|!v.is_empty()))}
pub(super)fn bool_value(p:&Value,k:&str)->Option<bool>{p.get(k).and_then(|v|match v{Value::Bool(b)=>Some(*b),Value::String(s)=>match s.trim(){"true"|"1"=>Some(true),"false"|"0"=>Some(false),_=>None},_=>None})}pub(super)fn i64_value(p:&Value,k:&str)->Option<i64>{p.get(k).and_then(|v|match v{Value::Number(n)=>n.as_i64(),Value::String(s)=>s.trim().parse().ok(),_=>None})}fn text_json(v:&Value)->Option<String>{match v{Value::String(s)=>Some(s.trim().to_owned()),Value::Number(n)=>Some(n.to_string()),_=>None}.filter(|s|!s.is_empty())}pub(super)fn string_list_value(p:&Value,k:&str)->Option<Vec<String>>{match p.get(k)?{Value::Array(a)=>Some(a.iter().filter_map(text_json).collect()),Value::String(s)=>Some(s.split([',',';','\n']).map(str::trim).filter(|v|!v.is_empty()).map(str::to_owned).collect()),_=>None}}
#[derive(Clone,Debug,Default,PartialEq)]pub(super)struct SaveIrsSettingsPayload{pub(super)enabled:Option<bool>,pub(super)merchant_id:Option<String>,pub(super)password:Option<String>,pub(super)pin:Option<String>,pub(super)secret:Option<String>,pub(super)endpoint_url:Option<String>,pub(super)allowed_ips:Option<Vec<String>>,pub(super)seller_margin_flat:Option<i64>,pub(super)callback_enabled:Option<bool>,pub(super)callback_url:Option<String>,pub(super)formatter:Option<Value>}impl SaveIrsSettingsPayload{pub(super)fn from_value(p:&Value)->Self{Self{enabled:bool_value(p,"enabled"),merchant_id:text_value(p,&["merchantId","merchant_id"]),password:text_value(p,&["password","pass"]),pin:text_value(p,&["pin"]),secret:text_value(p,&["secret","id"]),endpoint_url:text_value(p,&["endpointUrl"]),allowed_ips:string_list_value(p,"allowedIps"),seller_margin_flat:i64_value(p,"sellerMarginFlat"),callback_enabled:bool_value(p,"callbackEnabled"),callback_url:text_value(p,&["callbackUrl"]),formatter:p.get("formatter").cloned()}}}
